"""Serialize links whose two endpoints were read. No project leads are invented."""
from build_dossier import ROOT,groups,pages,items
import csv,json,re
ii={i['internal_key']:i for i in items}
refs={r['key']:r for r in json.loads((ROOT/'reference_evidence.json').read_text())}
rows=[]
def coords(cs):
    return '; '.join(f'{c}:{s:03d} (transcription file lines {pages[c,s]["start"]}–{pages[c,s]["end"]})' for c,s in cs)
def notes(keys):return ';'.join(dict.fromkeys(n for k in keys for n in ii[k]['sources']))
def F(a,b,keys,what,evidence):
    rows.append({'kind':'folder','from':coords(a),'to':coords(b),'what':what,'evidence':'Both endpoints read directly. '+evidence+' Items: '+';'.join(groups[k] for k in keys),'note_ids':notes(keys)})
def P(cs,ref,loc,keys,what,limit=''):
    r=refs[ref]
    rows.append({'kind':'published work','from':coords(cs),'to':ref+'; '+loc+'; '+r['url'],'what':what,'evidence':'Manuscript endpoint and specified published passage read. '+r['verification_scope']+'. '+limit+' Items: '+';'.join(groups[k] for k in keys),'note_ids':notes(keys)})

