# The complete package was already read. This final named-project search is an
# extraction audit, not a substitute for reading or a license to access projects.
source=ROOT.parents[1]/'sources/SA15_notes/pro/MPL_5+6_001-037_notes.md'
pattern=re.compile(r'La Longue Marche|Les Dérivateurs|Derivateurs|Dérivateurs|\bS6\b|\bLLM\b|research runs?|run names?',re.I)
hits=[(n,l) for n,l in enumerate(source.read_text().splitlines(),1) if pattern.search(l)]
assert not hits, 'Read and classify any named-project hit before emitting a lead: '+repr(hits)
with (ROOT/'project_leads.tsv').open('w') as f:
    csv.writer(f,delimiter='\t').writerow(fields)
(ROOT/'outputs/project_lead_audit.json').write_text(json.dumps({'source':str(source.relative_to(ROOT.parents[1])),'source_entries_read':444,'named_project_patterns':pattern.pattern,'hits':hits,'result':'No La Longue Marche, Dérivateurs, S6 or named research-run project lead occurs in this package. Earlier-run own ideas are retained in items, not fabricated as external project links. No external project endpoint was accessed.'},ensure_ascii=False,indent=2)+'\n')
print(f'Saved {len(rows)} within-package/published links, and an empty audited project-lead table.')
